def send(points, note='', cameras=('practice_cam',), fps=5):
 global command,seq
 p=np.asarray(points)
 if p.shape[1]==3: p=np.column_stack([p,np.tile(quat,(len(p),1))])
 result=None
 for k in range(0,len(p),190):
  a=p[k:k+190]; seq+=1
  np.save(ROOT/f'action_{seq:03}.npy',a)
  result=r.submit('ee_pose',a,dt=.05,cameras=list(cameras),video='frames',video_fps=fps,note=note)
  result.save(str(ROOT/f'run_{seq:03}'))
  for c,im in result.last.items(): Image.fromarray(im).save(ROOT/f'latest_{c}.png')
  command=a[-1].copy()
  print('action',seq,'steps',result.meta.get('control_steps'),'tip',result.group('tcp_pose',now=True)[:3].round(6),'plan',result.meta.get('plan'),flush=True)
  if result.stopped or result.done: raise RuntimeError(result.meta)
 return result

def line(end,speed=.02,hold=0,**kw):
 end=np.asarray(end); start=command[:3]
 n=max(1,int(np.ceil(np.linalg.norm(end-start)/speed/.05)))
 points=np.linspace(start,end,n+1)[1:]
 if hold: points=np.concatenate([points,np.tile(end,(round(hold/.05),1))])
 return send(points,**kw)

def up(z=.065):return line([*command[:2],z],speed=.035,hold=.2)
def move(x,y,z=.065):return line([x,y,z],speed=.08,hold=.25)
